func TestFortinetContentSelection(t *testing.T) {
	v := VulnInfo{CveContents: CveContents{
		Trivy:    {{Type: Trivy, Summary: "Trivy summary"}},
		Fortinet: {{Type: Fortinet, Title: "Fortinet title", Summary: "Fortinet summary", Cvss3Score: 8.1, Cvss3Vector: "CVSS:3.1/AV:N"}},
		Nvd:      {{Type: Nvd, Summary: "NVD summary", Cvss3Score: 7.5}},
		GitHub:   {{Type: GitHub, Summary: "GitHub summary"}},
	}}
	if got, want := v.Titles("en", ""), []CveContentStr{{Trivy, "Trivy summary"}, {Fortinet, "Fortinet title"}, {Nvd, "NVD summary"}}; !reflect.DeepEqual(got[:3], want) {
		t.Fatalf("Titles() = %v, want prefix %v", got, want)
	}
	if got, want := v.Summaries("en", ""), []CveContentStr{{Trivy, "Trivy summary"}, {Fortinet, "Fortinet summary"}, {Nvd, "NVD summary"}, {GitHub, "GitHub summary"}}; !reflect.DeepEqual(got[:4], want) {
		t.Fatalf("Summaries() = %v, want prefix %v", got, want)
	}
	if got := v.Cvss3Scores(); len(got) < 2 || got[0].Type != Fortinet || got[1].Type != Nvd {
		t.Fatalf("Cvss3Scores() = %v, want Fortinet before NVD", got)
	}
}

